package com.fitpulse.model.entity;
import com.fitpulse.model.enums.ContentStatus; import jakarta.persistence.*; import java.time.LocalDateTime;
@Entity @Table(name="gym_suggestions") public class GymSuggestion { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @ManyToOne @JoinColumn(name="submitted_by") private User submittedBy; @Column(nullable=false,length=150) private String name; @Column(nullable=false,length=100) private String cityName; @Column(nullable=false,length=300) private String address; @Column(length=500) private String websiteUrl; @Column(nullable=false,length=2000) private String details; @Enumerated(EnumType.STRING) @Column(nullable=false,length=30) private ContentStatus status=ContentStatus.PENDING; @Column(length=1000) private String adminNote; @Column(nullable=false) private LocalDateTime createdAt; @PrePersist void create(){createdAt=LocalDateTime.now();} public Long getId(){return id;} public User getSubmittedBy(){return submittedBy;} public void setSubmittedBy(User v){submittedBy=v;} public String getName(){return name;} public void setName(String v){name=v;} public String getCityName(){return cityName;} public void setCityName(String v){cityName=v;} public String getAddress(){return address;} public void setAddress(String v){address=v;} public String getWebsiteUrl(){return websiteUrl;} public void setWebsiteUrl(String v){websiteUrl=v;} public String getDetails(){return details;} public void setDetails(String v){details=v;} public ContentStatus getStatus(){return status;} public void setStatus(ContentStatus v){status=v;} public String getAdminNote(){return adminNote;} public void setAdminNote(String v){adminNote=v;}  @Column(length=50) private String phone; @Column(length=1000) private String priceInfo; @Column(length=1000) private String imageUrl; @ManyToOne @JoinColumn(name="published_gym_id") private Gym publishedGym; public String getPhone(){return phone;} public void setPhone(String value){phone=value;} public String getPriceInfo(){return priceInfo;} public void setPriceInfo(String value){priceInfo=value;} public String getImageUrl(){return imageUrl;} public void setImageUrl(String value){imageUrl=value;} public Gym getPublishedGym(){return publishedGym;} public void setPublishedGym(Gym value){publishedGym=value;} }
